<?php
if(!defined('ABSPATH')){exit;}
function vibelab_v2_support_pages(){return function_exists('vne_support_pages')?vne_support_pages():array('ho-tro'=>'Trợ giúp và liên hệ','gioi-thieu'=>'Về VibeLab Việt','tieu-chi'=>'Tiêu chí tuyển chọn','quyen-rieng-tu'=>'Quyền riêng tư','dieu-kien'=>'Điều kiện sử dụng','cau-hoi'=>'Câu hỏi thường gặp','bao-loi'=>'Báo lỗi nội dung');}
function vibelab_v2_support_url($page='ho-tro',$args=array()){if(isset(vibelab_v2_support_paths()[$page]))return add_query_arg($args,home_url('/'.vibelab_v2_support_paths()[$page].'/'));return add_query_arg(array_merge(array('vne_support'=>$page),$args),home_url('/'));}
function vibelab_v2_support_current(){return $GLOBALS['vne_support_context']??null;}
function vibelab_v2_support_fallback(){
    if(!isset($_GET['vne_support'])||vibelab_v2_support_current()){return;}
    $page=is_string($_GET['vne_support'])?$_GET['vne_support']:'';
    $status=isset(vibelab_v2_support_pages()[$page])?($page==='bao-loi'?503:200):404;
    $error=$status===200?null:new WP_Error('support','Trang chưa sẵn sàng hoặc không tồn tại.',array('status'=>$status));
    if($status!==200){status_header($status);nocache_headers();}
    $GLOBALS['vne_support_context']=array('page'=>$page,'error'=>$error,'values'=>array(),'item'=>null,'receipt'=>null);
}
add_action('template_redirect','vibelab_v2_support_fallback',3);
add_filter('template_include',function($template){return vibelab_v2_support_current()?__DIR__.'/../support-template.php':$template;},40);
add_filter('document_title_parts',function($parts){$ctx=vibelab_v2_support_current();if($ctx){$parts['title']=vibelab_v2_support_pages()[$ctx['page']]??'Không tìm thấy trang hỗ trợ';}return $parts;},40);
add_filter('wp_robots',function($robots){$ctx=vibelab_v2_support_current();if($ctx&&($ctx['page']==='bao-loi'||$ctx['error'])){$robots['noindex']=true;$robots['nofollow']=true;unset($robots['index']);}return $robots;});
function vibelab_v2_report_link($item){
    if(!function_exists('vne_report_submit')||empty($item['derived']['is_public'])){return;}
    echo '<p class="report-link"><a href="'.esc_url(vibelab_v2_support_url('bao-loi',array('resource'=>$item['id']))).'">Báo lỗi nội dung này</a> · Không gửi API key, mật khẩu hoặc dữ liệu khách hàng.</p>';
}
function vibelab_v2_support_content($page){
    $help=esc_url(vibelab_v2_support_url());$criteria=esc_url(vibelab_v2_support_url('tieu-chi'));$privacy=esc_url(vibelab_v2_support_url('quyen-rieng-tu'));
    $pages=array(
'gioi-thieu'=>'<p>VibeLab Việt là thư viện tài nguyên tiếng Việt cho người mới tiếp cận vibe coding và làm việc với AI agent. Mục tiêu là giúp bạn hiểu một công cụ dùng làm gì, cần chuẩn bị gì và nên bắt đầu bằng việc nhỏ nào.</p><h2>Bạn có thể làm gì ở đây?</h2><ul><li>Duyệt danh mục, tìm tài nguyên theo nhu cầu và công cụ.</li><li>Đọc trang chi tiết để xem nguồn, yêu cầu, chi phí ngoài và tình trạng kiểm chứng.</li><li>Mở đúng repo hoặc thư mục của tác giả; làm bài thực hành và tự đối chiếu kết quả.</li></ul><h2>Thư viện biên tập thế nào?</h2><p>Phần giới thiệu tiếng Việt do thư viện biên soạn; mã nguồn gốc và giấy phép thuộc tác giả tương ứng. Nguồn được ghi tại từng tài nguyên. Ảnh bìa minh họa không phải bằng chứng đã chạy thử.</p><p>Không lấy số sao, ảnh đẹp hoặc lời AI làm chứng nhận chất lượng. Xem <a href="'.$criteria.'">tiêu chí tuyển chọn và ý nghĩa trạng thái</a> trước khi chọn.</p><h2>Phạm vi hiện tại</h2><p>Website miễn phí, không có giỏ hàng hay thanh toán. Đọc bài không cần kết nối API. Công cụ bên ngoài có điều kiện tài khoản, quyền sử dụng và chi phí riêng; thư viện không bán hoặc vận hành thay tác giả repo.</p><p>Tên VibeLab Việt đang được thử nghiệm. Website không tự nhận là đại diện chính thức của nhà cung cấp AI hoặc tác giả tài nguyên. Có góp ý về nội dung? Xem <a href="'.$help.'">cách báo lỗi và xử lý phản hồi</a>.</p>',
'tieu-chi'=>'<p>Ưu tiên tài nguyên giải quyết được một việc cụ thể cho người mới. Nhiều sao hoặc đang được nhắc tới chỉ là tín hiệu khám phá, không đủ để khuyến nghị.</p><h2>Trước khi giới thiệu</h2><ol><li>Xác định đúng repo, thư mục hoặc tệp nguồn và mốc đối chiếu.</li><li>Nêu công dụng, ai phù hợp, điều kiện cài/chạy và công cụ liên quan.</li><li>Đọc thông tin chi phí, giấy phép và quyền truy cập; thiếu dữ liệu thì ghi chưa xác định, không suy ra miễn phí hoặc an toàn.</li><li>Phân biệt nguồn tác giả công bố với kết quả thư viện tự chạy; có mâu thuẫn thì giữ cảnh báo.</li><li>Kiểm tra ngôn ngữ hướng dẫn, liên kết và đường đi cho người mới trước khi biên tập xuất bản.</li></ol><h2>Đọc nhãn tình trạng</h2><dl><dt>Chưa thử</dt><dd>Chưa có bằng chứng chạy thử cho phiên bản hiện tại. Đã đọc nguồn không đồng nghĩa đã cài.</dd><dt>Đã thử</dt><dd>Có bằng chứng với phiên bản, môi trường, đầu vào, kết quả và checklist đã ghi. Phạm vi đó không bảo đảm mọi máy hoặc mọi lần AI tạo mã đều giống nhau.</dd><dt>Cần kiểm tra lại</dt><dd>Bài, nguồn phụ thuộc hoặc điều kiện đã thay đổi; bằng chứng cũ vẫn là lịch sử. Khối lệnh có thể bị ẩn.</dd><dt>Chưa xác minh truy cập</dt><dd>Chưa có quan sát truy cập hiện hành; không tự kết luận nguồn đã bị xóa.</dd><dt>Nguồn không truy cập được / đã archived</dt><dd>Đọc ghi chú và mốc đối chiếu. Không suy rằng repo vẫn đang được duy trì.</dd><dt>Tạm ngừng khuyến nghị</dt><dd>Thư viện giữ giải thích nhưng ngừng đề xuất dùng. Nút mở nguồn có thể được thay bằng xem lý do.</dd></dl><h2>Khi phát hiện thay đổi</h2><p>Người biên tập đối chiếu báo lỗi với nguồn và phiên bản liên quan, rồi sửa hoặc bổ sung cảnh báo qua quy trình duyệt. Một báo cáo không tự sửa tài nguyên, tự xuất bản hoặc tự chạy repo.</p><p>Hiện không có lời hứa quét mọi nguồn hằng ngày, số lượng bài mới cố định, điểm an toàn hay đánh giá cộng đồng. <a href="'.$help.'">Báo vấn đề bạn quan sát được</a>.</p>',
'quyen-rieng-tu'=>'<p>Phần này mô tả dữ liệu của tính năng báo lỗi và checklist trên website. Không gửi API key, mật khẩu, nội dung khách hàng hoặc tệp cấu hình có bí mật.</p><h2>Biểu mẫu lưu những gì?</h2><p>Khi gửi thành công, hàng đợi riêng lưu loại vấn đề, mô tả, email nếu bạn tự cung cấp, thời điểm gửi và tài nguyên/phiên bản liên quan. Không có đính kèm, tải file hoặc trường yêu cầu mật khẩu. Bạn có thể bỏ trống email.</p><p>Email tùy chọn chỉ nhằm giúp người biên tập có thông tin liên hệ về báo cáo nếu cần; không dùng form này để đăng ký nhận tin. Hiện không có email tự động hay cam kết phản hồi.</p><h2>Ai xem và xử lý?</h2><p>Người có quyền biên tập thư viện trong WordPress được xem và xóa hàng đợi. Nội dung báo cáo và email không được công khai trên trang tài nguyên, tìm kiếm, feed hoặc API công khai.</p><p>Người biên tập cần xóa báo cáo khi không còn cần và rà soát các báo cáo quá 30 ngày. Bản này không có lịch xóa tự động. Xóa trong hàng đợi là xóa khỏi database hiện tại; bản sao lưu có vòng đời riêng, không có cam kết tự xóa đồng thời.</p><h2>Chống gửi lặp và spam</h2><p>Form dùng mã phiên, ô bẫy bot và giới hạn gửi. Địa chỉ IP trực tiếp được dùng để tạo mã băm theo khoảng thời gian cho giới hạn tần suất; form không lưu IP thô hoặc tin cậy địa chỉ do người gửi tự khai. Cấu hình proxy có thể ảnh hưởng giới hạn.</p><p>Nhật ký máy chủ, sao lưu và dịch vụ hạ tầng thuộc cấu hình hosting. Không suy từ cách lưu của biểu mẫu rằng máy chủ không ghi nhật ký; các tầng này cần được đối chiếu trước khi mở website chính thức.</p><h2>Dữ liệu trên trình duyệt</h2><p>Checklist bài học lưu mã bài, phiên bản và các mục bạn tự chọn trong localStorage khi trình duyệt cho phép. Không đồng bộ tài khoản, không gửi dấu chọn lên server. Dùng nút bỏ dấu trong bài hoặc xóa dữ liệu website trong trình duyệt để dọn.</p><p>Biểu mẫu báo lỗi không lưu nháp vào localStorage. Phiên xác nhận gửi chỉ hiện mã báo cáo, không chứa mô tả hoặc email. Hết phiên xác nhận không có nghĩa báo cáo đã bị xóa.</p><h2>Liên hệ về dữ liệu đã gửi</h2><p>Từ một tài nguyên hoặc bài học công khai, chọn Báo lỗi nội dung này, chọn Vấn đề khác và nêu mã báo cáo cùng yêu cầu sửa/xóa. Nếu nội dung gốc đã bị ẩn, bạn có thể dùng một nội dung công khai khác làm nơi mở biểu mẫu; ghi rõ yêu cầu liên quan báo cáo cũ. Không gửi lại bí mật hoặc thông tin nhận dạng không cần thiết. Người biên tập phải đối chiếu trước khi xử lý; chưa có tài khoản khách hoặc cơ chế tự phục vụ tra cứu báo cáo riêng.</p>',
'dieu-kien'=>'<p>Bạn có thể đọc thư viện miễn phí. Website giới thiệu và hướng dẫn; không cung cấp thanh toán, không đại diện tác giả repo và không cam kết công cụ ngoài luôn hoạt động hoặc luôn miễn phí.</p><h2>Trước khi sử dụng tài nguyên</h2><p>Đọc nguồn, giấy phép, yêu cầu, quyền và phạm vi thử ở trang chi tiết. Tự xem điều kiện tài khoản/chi phí tại nhà cung cấp. Nhãn Đã thử chỉ áp dụng cho kết quả ghi trong bằng chứng, không bảo đảm tương thích với máy hoặc dữ liệu của bạn.</p><p>Liên kết Truy cập repo đưa bạn sang nguồn bên ngoài. Điều kiện, quyền riêng tư và giấy phép của nguồn đó do tác giả/nhà cung cấp quy định. Không suy việc có mặt trong danh mục là chứng nhận an toàn tuyệt đối.</p><h2>Làm bài thực hành</h2><p>Dùng thư mục thử riêng, giữ bản khôi phục, đọc tác dụng lệnh trước khi chạy. Không đưa khóa bí mật hay dữ liệu thật của khách hàng vào bài mẫu. Việc tích checklist hoặc sao chép lệnh không phải chứng nhận hoàn thành.</p><h2>Gửi phản hồi có trách nhiệm</h2><p>Chỉ gửi vấn đề liên quan nội dung, nêu điều quan sát được và tránh thông tin nhạy cảm. Không gửi spam, nội dung quấy rối hoặc yêu cầu chạy lệnh/tải file qua form. Báo cáo được người biên tập xem xét, không tự động xuất bản.</p><p>Thư viện có thể sửa nội dung, bổ sung cảnh báo hoặc ngừng khuyến nghị khi có căn cứ. Chưa có thời hạn hỗ trợ cam kết. Xem <a href="'.$privacy.'">quyền riêng tư của biểu mẫu</a> và <a href="'.$help.'">cách báo lỗi</a>.</p>',
'ho-tro'=>'<p>Bạn có thể đọc bài, tìm tài nguyên và mở repo mà không đăng ký tài khoản website hoặc nhập API key. Nếu gặp lỗi, hãy phân biệt lỗi nội dung với lỗi tài khoản hoặc công cụ ngoài.</p><h2>Báo lỗi một tài nguyên hoặc bài học</h2><ol><li>Mở trang chi tiết tài nguyên hoặc bài thực hành liên quan.</li><li>Chọn Báo lỗi nội dung này. Form tự gắn đúng nội dung và phiên bản.</li><li>Chọn loại vấn đề, mô tả bước đã làm và kết quả quan sát được. Email là tùy chọn.</li><li>Chỉ coi website đã nhận khi thấy thông báo Đã lưu báo cáo cùng mã xác nhận.</li></ol><p>Báo cáo được lưu vào hàng đợi riêng của người biên tập WordPress. Không gửi email tự động, không tự sửa tài nguyên và không tự chạy repo. Chưa có người trực hoặc thời gian phản hồi cam kết.</p><h2>Nếu gửi thất bại</h2><p>Đọc thông báo ở biểu mẫu. Lỗi nhập liệu cần sửa trường được chỉ ra; phiên hết hạn cần mở lại form; gửi quá nhiều cần chờ khoảng 15 phút. Khi lưu lỗi, không có thông báo thành công giả; bạn có thể thử lại cùng biểu mẫu để tránh tạo bản trùng.</p><h2>Vấn đề tài khoản hoặc công cụ ngoài</h2><p>Kiểm tra thông báo tại nhà cung cấp. Website không đăng nhập, mở khóa hạn mức hoặc khôi phục tài khoản thay bạn. Không gửi mật khẩu hoặc API key qua báo lỗi.</p><h2>Liên hệ về website</h2><p>Kênh hiện có là báo lỗi theo nội dung; với vấn đề giao diện hoặc dữ liệu liên quan, chọn Vấn đề khác và mô tả nơi gặp lỗi. Chưa có hộp thư hỗ trợ riêng, live chat, diễn đàn hay form đề xuất repo mới. Không có địa chỉ email hoặc số điện thoại giả để liên hệ.</p>',
'cau-hoi'=>'<details><summary>Website miễn phí thì dùng công cụ ngoài có mất phí không?</summary><p>Đọc website miễn phí. Tài khoản, hạn mức, API và dịch vụ ngoài có điều kiện riêng. Xem phần chi phí/yêu cầu ở tài nguyên và nguồn nhà cung cấp; chưa xác định không có nghĩa bằng 0.</p></details><details><summary>Truy cập repo khác Xem chi tiết thế nào?</summary><p>Xem chi tiết mở phần giới thiệu, điều kiện và bằng chứng trong thư viện. Truy cập repo mở nguồn gốc ở tab mới. Nếu nguồn bị hạn chế hoặc tạm ngừng khuyến nghị, hãy đọc tình trạng trước.</p></details><details><summary>Nhãn Đã thử có bảo đảm an toàn và chạy được trên máy tôi?</summary><p>Không. Nhãn áp dụng cho phiên bản và môi trường trong bằng chứng. Đọc giới hạn, quyền và điều kiện của tài nguyên; không dùng nhãn đó như chứng nhận cho mọi máy hoặc mọi dữ liệu.</p></details><details><summary>Tôi chưa biết cài công cụ, bắt đầu ở đâu?</summary><p>Chọn Tôi mới bắt đầu hoặc Hướng dẫn thực hành. Bài mở đầu hướng tới landing page cho một dịch vụ hư cấu trên Windows. Đọc điều kiện, xem đầu ra mẫu và làm từng bước; chưa đủ quyền tài khoản thì có thể dừng để đọc.</p></details><details><summary>Có cần đưa API key để đọc bài hay gửi báo lỗi?</summary><p>Không. Biểu mẫu không yêu cầu và không được dùng để gửi API key, mật khẩu hoặc dữ liệu khách hàng. Không dán tệp cấu hình hay log chưa che bí mật.</p></details><details><summary>Đánh dấu đủ checklist có nghĩa website đã kiểm tra bài của tôi?</summary><p>Không. Đó là ghi chú tự kiểm tra trên trình duyệt của bạn. Website không đọc máy, không chạy mã và không cấp chứng chỉ từ các dấu chọn.</p></details><details><summary>Báo lỗi có được công khai hoặc trả lời ngay?</summary><p>Không công khai nội dung báo cáo/email. Báo cáo vào hàng đợi riêng để người có quyền biên tập xem xét; chưa có thời gian phản hồi cam kết và không có email tự động.</p></details><details><summary>Tôi bấm gửi rồi tải lại, có tạo hai báo cáo không?</summary><p>Gửi thành công chuyển sang trang xác nhận. Tải lại trang đó không gửi lại form. Gửi lặp cùng mã phiên cũng không tạo bản mới; một form mới là một yêu cầu mới và vẫn chịu giới hạn.</p></details>'
    );
    return $pages[$page]??'';
}
